    "feat.date_15_sep": "15 September",
    "feat.desc1": "Eliminate unpredictable lines at Primary Health Centres. Frontline workers can pre-book confirmed slots with local Medical Officers or teleconsultation physicians.",
    "feat.desc2": "Clinical priority algorithms assess vital signs recorded by ASHA workers to highlight urgent symptoms, accelerating clinical attention for vulnerable cases like maternal hypertension.",
    "feat.desc3": "Prevent drop-offs when moving from rural sub-centres to specialty hospitals. Every referral is secured with a persistent ID and QR token that tracks the patient until final specialist review.",
    "feat.desc4": "Healthcare doesn't stop after the doctor's visit. Actionable care plans automatically generate scheduled reminders for ASHA workers to monitor recovery, medication adherence, and follow-up tests.",
    "feat.desc5": "Rural patients frequently travel hours only to find stockouts. This feature provides ASHA workers with real-time visibility into drug inventories and diagnostic test capabilities at neighboring health centers.",
