    "gov.title": "Government of Maharashtra",
    "hist.body_text": "Maharashtra Medical Council is the oldest body and successor body of the old Bombay Medical Council, which was established in September,1912 and was in existence till bifurcation of old Bombay State. The first meeting of the Bombay Medical Council was held on 24th September, 1912 under the President ship of Mr. H. W. Stevenson. In his speech Mr. H. W. Stevenson said that, there is a vast difference between liberty and license. He further said that, registration of medical man stamps him with the approval of the Government of the Country and it is accepted as a guarantee of his professional integrity.",
    "hist.ethics_desc": "In the year 1929 the Bombay Municipal Corporation, in its meeting held on 27th October, 1929, unanimously passed a resolution that, private dispensaries, who dispense medicine after examination of patient and where there is no sale of medical drugs should be exempted of payment for Shop Act. In 1917 Government of Bombay amended the Bombay Medical Council Act, 1912 and made the provision of reciprocal registration system between the two Councils.",
    "hist.ethics_title": "Cornerstone of Medical Ethics (1912)",
    "hist.mmc_mumbai": "Maharashtra Medical Council, Mumbai",
    "hist.statutory_authority": "Statutory Regulatory Authority",
    "home.about_badge": "Statutory Regulatory Body",
    "home.about_btn": "Learn More About MMC Mandate ➔",
    "home.about_desc1": "Established under the Maharashtra Medical Council Act, 1965, the Council safeguards ethical medical practice, registers medical practitioners, and oversees medical education across Maharashtra.",
    "home.about_desc2": "This prototype explores digital models to support rural practitioners, empower frontline community health workers (ASHA), and prevent patient drop-offs across rural-urban healthcare transitions.",
    "home.about_title": "Maharashtra Medical Council, Mumbai",
    "home.apex_body": "Apex Medical Regulatory Body of Maharashtra",
    "home.apex_leadership": "Apex Leadership",
    "home.badge": "Government of Maharashtra • Healthcare Initiative",
    "home.council_hq": "Council Headquarters",
    "home.cta_complaints": "File Complaint / Grievance",
    "home.cta_features": "Explore Core Features ➔",
    "home.est_1912": "Est. 1912",
    "home.feat1_desc": "Eliminate chaotic OPD lines. Frontline workers pre-book confirmed slots with local Medical Officers and district specialists.",
    "home.feat1_title": "Appointment & Slot Booking",
    "home.feat2_desc": "Standardized red/yellow/green clinical risk score flags high-risk patients for earlier Medical Officer review before complications arise.",
    "home.feat2_title": "Risk-Based Earlier Consultation",
    "home.feat3_desc": "Generate unique Referral IDs and digital clinical summaries that eliminate paper loss between Primary Health Centres and Civil Hospitals.",
    "home.feat3_title": "E-Referral & Referral ID",
    "home.feat4_desc": "Continuous post-consultation care protocols with automated check-in reminders for maternal care, hypertension, and diabetes.",
    "home.feat4_title": "Structured Care Plan & Follow-Up",
    "home.feat5_desc": "Real-time stock visibility so patients never travel hours only to find essential medicines or diagnostic labs out of stock.",
    "home.feat5_title": "Medicine & Diagnostic Availability",
    "home.hero_slogan": "“आरोग्य प्रत्येक गावापर्यंत.”",
    "home.hero_subtitle": "Maharashtra Medical Council prototype connecting frontline ASHA workers, Primary Health Centres, and Sub-District Hospitals for timely triage, smart e-referrals, and continuous patient follow-up.",
    "home.hero_title": "Healthcare, within reach of every village.",
    "home.impact_c1_desc": "Pre-verification of medicine stocks and slots prevents futile journeys to town hospitals.",
    "home.impact_c1_title": "Reduced Travel",
    "home.impact_c2_desc": "High-priority flags ensure hypertensive mothers receive care within hours instead of days.",
    "home.impact_c2_title": "Earlier Consultation",
    "home.impact_c3_desc": "Referral IDs and QR tokens prevent patient drop-offs between primary and district centers.",
    "home.impact_c3_title": "Trackable Referrals",
    "home.impact_c4_desc": "Automated task cues ensure maternal and chronic care plans are followed through diligently.",
    "home.impact_c4_title": "Follow-Up Rate",
    "home.impact_subtitle": "Tangible real-world outcomes demonstrated across pilot talukas in Maharashtra.",
    "home.impact_tag": "Measurable Benefits",
    "home.impact_title": "Bridging the Rural Healthcare Divide",
    "home.leader_name": "Dr. Vinky Rughwani",
    "home.leader_role": "President, Maharashtra Medical Council, Mumbai",
    "home.mumbai": "Mumbai",
