    "feat.care_task2_title": "आईएफए एवं कैल्शियम गोली सेवन सत्यापन",
    "feat.category_anc": "मातृ देखभाल (ANC)",
    "feat.date_15_sep": "15 सितंबर",
    "feat.desc1": "प्राथमिक स्वास्थ्य केंद्रों पर अनिश्चित कतारों को समाप्त करें। आशा कार्यकर्ता स्थानीय चिकित्सा अधिकारियों या टेली-परामर्श डॉक्टरों के साथ पुष्ट स्लॉट पहले से बुक कर सकती हैं।",
    "feat.desc2": "नैदानिक प्राथमिकता एल्गोरिदम आशा कार्यकर्ताओं द्वारा दर्ज वाइटल्स का आकलन करते हैं ताकि मातृ उच्च रक्तचाप जैसे संवेदनशील मामलों में तुरंत चिकित्सकीय ध्यान मिल सके।",
    "feat.desc3": "ग्रामीण उप-केंद्रों से विशेषज्ञ अस्पतालों में जाते समय मरीजों के छूट जाने को रोकें। प्रत्येक रेफरल एक स्थायी आईडी और क्यूआर टोकन के साथ सुरक्षित रहता है जो अंतिम विशेषज्ञ समीक्षा तक मरीज को ट्रैक करता है।",
    "feat.desc4": "डॉक्टर से मिलने के बाद स्वास्थ्य सेवा समाप्त नहीं होती। कार्रवाई योग्य देखभाल योजनाएं आशा कार्यकर्ताओं के लिए स्वचालित रूप से अनुस्मारक उत्पन्न करती हैं ताकि वे ठीक होने, दवा लेने और अनुवर्ती परीक्षणों की निगरानी कर सकें।",
    "feat.desc5": "ग्रामीण मरीज अक्सर घंटों यात्रा करके पहुंचते हैं और पाते हैं कि दवाइयां खत्म हैं। यह सुविधा आशा कार्यकर्ताओं को नजदीकी स्वास्थ्य केंद्रों में दवा के स्टॉक और नैदानिक परीक्षण सुविधाओं की वास्तविक समय की जानकारी देती है।",
    "feat.diag_lbl": "जांच सुविधाएं:",
