    "feat.quote1": "“अपॉइंटमेंट और स्लॉट दृश्यता मरीजों को अनावश्यक प्रतीक्षा से बचाती है और आशा कार्यकर्ताओं को योजना बनाने में मदद करती है।”",
    "feat.quote2": "“यह प्रणाली अग्रणी कार्यकर्ताओं को उन मरीजों की पहचान करने में मदद करती है जिन्हें तुरंत पेशेवर जांच की आवश्यकता है।”",
    "feat.quote3": "“मरीज द्वारा प्राथमिक स्वास्थ्य केंद्र छोड़ने के बाद भी रेफरल समाप्त होने के बजाय ट्रैक करने योग्य बना रहता है।”",
    "feat.quote4": "“देखभाल योजनाएं और अनुस्मारक आशा कार्यकर्ताओं को यह ट्रैक करने में मदद करते हैं कि किन मरीजों को कब फॉलो-अप की आवश्यकता है।”",
    "feat.quote5": "“आशा कार्यकर्ता मरीज को भेजने से पहले यह पता लगा सकती हैं कि दवाइयां या जांच कहां उपलब्ध हैं, जिससे अनावश्यक यात्रा कम होती है।”",
    "feat.ref_from_to": "से: उप-केंद्र वडगांव ➔ तक: ग्रामीण अस्पताल वडगांव",
