    "feed.ref_badge": "संदर्भ: FB-8492",
    "feed.ref_desc": "आपकी बहुमूल्य प्रतिक्रिया दर्ज कर ली गई है और महाराष्ट्र मेडिकल काउंसिल गुणवत्ता आश्वासन समिति को प्रस्तुत कर दी गई है। आपकी राय सीधे ग्रामीण स्वास्थ्य सेवा में सुधार का मार्गदर्शन करती है।",
