    "feed.review1_srv": "सेवा: अपॉइंटमेंट",
    "feed.review1_text": "“हमारी आशा कार्यकर्ता सुनीता ने हमारी PHC वडगांव अपॉइंटमेंट पहले से बुक कर दी। मुझे अपनी बुजुर्ग माँ के साथ सुबह की कतारों में नहीं खड़ा होना पड़ा।”",
    "feed.review2_author": "रमेश शिंदे",
    "feed.review2_loc": "📍 बारामती ग्रामीण, पुणे •",
    "feed.review2_srv": "सेवा: रेफरल",
    "feed.review2_text": "“डिजिटल रेफरल आईडी REF-1024 से उप-जिला अस्पताल पहुँचना बेहद आसान हो गया। पहुँचते ही डॉक्टरों के पास हमारी पूरी जांच रिपोर्ट तैयार थी।”",
    "feed.review3_author": "पूजा गायकवाड़",
    "feed.review3_loc": "📍 खेड तालुका, पुणे •",
