    "feed.review3_text": "“दवा स्टॉक संकेतक बहुत उपयोगी है। PHC जाने के लिए 6 किमी यात्रा करने से पहले ही हम देख सके कि आयरन की गोलियां और ओआरएस उपलब्ध हैं।”",
