    "gov.logout": "लॉगआउट",
    "gov.title": "महाराष्ट्र शासन",
    "hist.body_text": "महाराष्ट्र मेडिकल काउंसिल सबसे पुराना और पूर्व बॉम्बे मेडिकल काउंसिल का उत्तराधिकारी निकाय है, जिसकी स्थापना सितंबर 1912 में हुई थी और पुराने बॉम्बे राज्य के विभाजन तक अस्तित्व में रही। बॉम्बे मेडिकल काउंसिल की पहली बैठक 24 सितंबर 1912 को श्री एच. डब्ल्यू. स्टीवेन्सन की अध्यक्षता में हुई थी। अपने भाषण में श्री एच. डब्ल्यू. स्टीवेन्सन ने कहा था कि स्वतंत्रता और स्वच्छंदता में बहुत बड़ा अंतर है। उन्होंने आगे कहा कि चिकित्सक का पंजीकरण उसे देश की सरकार की मंजूरी देता है और इसे उसकी व्यावसायिक निष्ठा की गारंटी माना जाता है।",
    "hist.ethics_desc": "वर्ष 1929 में बॉम्बे नगर निगम ने 27 अक्टूबर 1929 को आयोजित अपनी बैठक में सर्वसम्मति से प्रस्ताव पारित किया कि मरीजों की जांच के बाद दवा देने वाले निजी दवाखानों को, जहां दवाओं की बिक्री नहीं होती, दुकान अधिनियम (Shop Act) के भुगतान से छूट दी जानी चाहिए। वर्ष 1917 में बॉम्बे सरकार ने बॉम्बे मेडिकल काउंसिल एक्ट, 1912 में संशोधन कर दोनों परिषदों के बीच पारस्परिक पंजीकरण प्रणाली का प्रावधान किया।",
    "hist.ethics_title": "चिकित्सा आचारसंहिता का आधारस्तंभ (1912)",
    "hist.mmc_mumbai": "महाराष्ट्र मेडिकल काउंसिल, मुंबई",
    "hist.statutory_authority": "वैधानिक नियामक प्राधिकरण",
    "home.about_badge": "वैधानिक नियामक निकाय",
    "home.about_btn": "परिषद के कार्य और अधिकार जानें ➔",
    "home.about_desc1": "महाराष्ट्र मेडिकल काउंसिल अधिनियम, 1965 के तहत गठित यह परिषद आधुनिक चिकित्सा पद्धतियों के पंजीकरण, नैतिक आचरण के संरक्षण और चिकित्सा शिक्षा की निगरानी करती है।",
    "home.about_desc2": "यह प्रोटोटाइप ग्रामीण क्षेत्रों में डॉक्टरों की सहायता, आशा कार्यकर्ताओं के सशक्तिकरण और रेफरल के दौरान मरीजों की देखरेख सुनिश्चित करने के लिए तैयार किया गया है।",
    "home.about_title": "महाराष्ट्र मेडिकल काउंसिल, मुंबई",
    "home.apex_body": "महाराष्ट्र का सर्वोच्च चिकित्सा नियामक निकाय",
    "home.apex_leadership": "शीर्ष नेतृत्व",
    "home.badge": "महाराष्ट्र शासन • स्वास्थ्य सेवा पहल",
    "home.council_hq": "काउंसिल मुख्यालय",
    "home.cta_complaints": "शिकायत दर्ज करें",
    "home.cta_features": "मुख्य सुविधाएं देखें ➔",
    "home.est_1912": "स्थापना १९१२",
    "home.feat1_desc": "ओपीडी की लंबी कतारों से मुक्ति। आशा कार्यकर्ता स्थानीय चिकित्सा अधिकारी या विशेषज्ञ के साथ पक्का समय पहले से बुक कर सकती हैं।",
    "home.feat1_title": "अपॉइंटमेंट व स्लॉट बुकिंग",
    "home.feat2_desc": "लाल/पीला/हरा नैदानिक जोखिम स्कोर, जिससे गंभीर मरीजों की पहचान पहले ही हो सके और समय रहते डॉक्टर द्वारा इलाज शुरू हो।",
    "home.feat2_title": "जोखिम-आधारित प्रारंभिक परामर्श",
    "home.feat3_desc": "डिजिटल रेफरल पर्ची और अद्वितीय आईडी, जिससे पीएचसी से जिला अस्पताल तक मरीज की जानकारी सुरक्षित रहती है और कागजात खोने का डर नहीं रहता।",
    "home.feat3_title": "ई-रेफरल व रेफरल आईडी",
    "home.feat4_desc": "परामर्श के बाद निरंतर देखभाल। मातृ स्वास्थ्य, उच्च रक्तचाप और मधुमेह के मरीजों के लिए स्वचालित फॉलो-अप स्मरण-पत्र।",
    "home.feat4_title": "संरचित देखभाल योजना व फॉलो-अप",
    "home.feat5_desc": "दवा स्टॉक की वास्तविक समय में जानकारी, ताकि किसी भी मरीज को अस्पताल जाकर दवा न मिलने पर खाली हाथ न लौटना पड़े।",
    "home.feat5_title": "दवा व जांच उपलब्धता",
    "home.hero_slogan": "“आरोग्य प्रत्येक गावापर्यंत।”",
    "home.hero_subtitle": "महाराष्ट्र मेडिकल काउंसिल का नवाचारी प्रोटोटाइप, जो ग्रामीण आशा कार्यकर्ताओं, प्राथमिक स्वास्थ्य केंद्रों और उप-जिला अस्पतालों को समय पर जांच, स्मार्ट ई-रेफरल और निरंतर मरीज फॉलो-अप से जोड़ता है।",
    "home.hero_title": "हर गाँव तक, बेहतर स्वास्थ्य सेवा की पहुँच।",
    "home.impact_c1_desc": "दवा स्टॉक और स्लॉट की पूर्व जांच से अस्पतालों की अनावश्यक यात्रा से बचाव।",
    "home.impact_c1_title": "यात्रा में बचत",
