    "feat.desc1": "प्राथमिक आरोग्य केंद्रांवरील अनिश्चित रांगा संपवा. आशा कार्यकर्त्या स्थानिक वैद्यकीय अधिकारी किंवा टेलि-सल्लामसलत डॉक्टरांकडे निश्चित स्लॉट आधीच बुक करू शकतात.",
    "feat.desc2": "वैद्यकीय प्राधान्य अल्गोरिदम आशा कार्यकर्त्यांनी नोंदवलेल्या वाइटल्सचे मूल्यमापन करतात, ज्यामुळे माता उच्च रक्तदाबासारख्या संवेदनशील प्रकरणांमध्ये तातडीने वैद्यकीय मदत मिळते.",
    "feat.desc3": "ग्रामीण उपकेंद्रांकडून विशेष रुग्णालयांकडे जाताना रुग्णांची गळती रोखा. प्रत्येक रेफरलला कायमस्वरूपी आयडी आणि QR टोकन दिले जाते, जे अंतिम तज्ज्ञ तपासणीपर्यंत रुग्णाचा मागोवा घेते.",
    "feat.desc4": "डॉक्टरांच्या भेटीनंतर आरोग्यसेवा थांबत नाही. कृतीयोग्य काळजी आराखडे आशा सेविकांसाठी नियोजित स्मरणपत्रे तयार करतात, जेणेकरून त्या रुग्णाच्या प्रकृतीची, औषध घेण्याची व तपासण्यांची खात्री करू शकतील.",
    "feat.desc5": "ग्रामीण रुग्ण तासनतास प्रवास करून पोहोचतात आणि औषधे उपलब्ध नसतात. हे वैशिष्ट्य आशा सेविकांना शेजारील आरोग्य केंद्रांमधील औषध साठा आणि निदान चाचण्यांची रिअल-टाइम माहिती देते.",
