    "feat.quote1": "“अपॉइंटमेंट आणि स्लॉट उपलब्धतेमुळे रुग्णांचा विनाकारण वेळ वाचतो आणि आशा कार्यकर्त्यांना भेटींचे नियोजन करण्यास मदत होते.”",
    "feat.quote2": "“ही प्रणाली आशा कार्यकर्त्यांना अशा रुग्णांची ओळख पटवण्यास मदत करते ज्यांना तातडीच्या वैद्यकीय तपासणीची गरज आहे.”",
    "feat.quote3": "“रुग्णाने प्राथमिक आरोग्य केंद्र सोडल्यावरही रेफरल संपत नाही, तर त्याचा पाठपुरावा करता येतो.”",
