    "feed.ref_desc": "आपला बहुमूल्य अभिप्राय नोंदवला गेला असून तो महाराष्ट्र मेडिकल कौन्सिल गुणवत्ता हमी समितीकडे सादर करण्यात आला आहे. आपला आवाज थेट ग्रामीण आरोग्य सुधारणांना दिशा देतो.",
