    "feed.review2_text": "“डिजिटल रेफरल आयडी REF-1024 मुळे उपजिल्हा रुग्णालयात जाणे सहज सोपे झाले. तेथे पोहोचल्यावर डॉक्टरांकडे आमचा सर्व तपासणी इतिहास तयार होता.”",
